"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/comparison/variants/02-bars";
export interface ArtemisComparisonBarsProps { className?: string;  }
export function ArtemisComparisonBars({ className }: ArtemisComparisonBarsProps) {return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View0/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { useId, useState } from "react";
import { motion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { CompareSelect, type Competitor } from "./02-bars/compare-select";
type Metric = {
    title: string;
    caption: string;
    workspace: number;
    rivals: Record<Competitor, number>;
};
const METRICS: readonly Metric[] = [
    { title: "Visual reasoning", caption: "Complex pattern recognition", workspace: 45.1, rivals: { "Option A": 31.1, "Option B": 23.8 } },
    { title: "Code repair", caption: "Issues resolved successfully", workspace: 39.6, rivals: { "Option A": 16.8, "Option B": 24.2 } },
    { title: "Security fixes", caption: "Vulnerabilities resolved", workspace: 74.4, rivals: { "Option A": 22.3, "Option B": 38.5 } },
];
const TICKS = [100, 75, 50, 25, 0] as const;
function Bar({ value, side, label, gradient, delay, }: {
    value: number;
    side: "art:left-0" | "art:right-0";
    label: string;
    gradient: string;
    delay: number;
}) {
    return (<div className={`art:absolute art:bottom-0 art:w-[45%] ${side}`} style={{ height: `${value}%` }}>
      <span className="art:absolute art:bottom-full art:left-0 art:right-0 art:mb-2 art:text-center art:text-xl art:font-medium art:tabular-nums">
        {String(value)}
        <span className="art:text-sm">{"%"}</span>
      </span>
      <motion.div className={`art:absolute art:inset-0 art:origin-bottom art:rounded-t-xl art:bg-gradient-to-t ${gradient}`} aria-hidden="true" initial={{ scaleY: 0 }} whileInView={{ scaleY: 1 }} viewport={{ once: true }} transition={{ duration: 0.6, ease: ARTEMIS_EASE_OUT, delay }}/>
      <span className="art:sr-only">{label}</span>
    </div>);
}
export default function ComparisonBars() {
    const headingId = useId();
    const [rival, setRival] = useState<Competitor>("Option A");
    return (<>
      <section className="art:w-full art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-24">
        <div className="art:mx-auto art:max-w-6xl">
          <div className="art:mx-auto art:max-w-2xl art:text-center">
            <p className="art:text-sm art:font-medium art:text-muted-foreground">
              {"Performance, compared"}
            </p>
            <h2 id={headingId} className="art:mt-4 art:text-balance art:text-4xl art:font-medium art:tracking-tight">
              {"A clearer view of what\u2019s possible."}
            </h2>
            <p className="art:mx-auto art:mt-5 art:max-w-xl art:text-pretty art:text-sm art:leading-6 art:text-muted-foreground art:@min-[640px]/artemis:text-base">
              {"Compare success rates across reasoning, code, and security. Same tasks. Same scale."}
            </p>
          </div>
          <div className="art:mt-10 art:flex art:flex-wrap art:items-center art:justify-between art:gap-5">
            <div className="art:flex art:flex-wrap art:items-center art:gap-5 art:text-sm">
              <span className="art:inline-flex art:items-center art:gap-2">
                <span aria-hidden="true" className="art:size-3 art:rounded-full art:bg-accent/70"/>
                {"Workspace"}
              </span>
              <span className="art:inline-flex art:items-center art:gap-2 art:text-muted-foreground">
                <span aria-hidden="true" className="art:size-3 art:rounded-full art:bg-foreground/20"/>
                {rival}
              </span>
            </div>
            <div className="art:flex art:items-center art:gap-3">
              <span className="art:text-sm art:text-muted-foreground">
                {"Compare with"}
              </span>
              <CompareSelect value={rival} onChange={setRival}/>
            </div>
          </div>
          <section aria-labelledby={headingId} tabIndex={0} className="art:mt-8 art:overflow-x-auto art:rounded-2xl art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring">
            <div className="art:relative art:pb-2 art:pl-10 art:pt-16" style={{ minWidth: "760px" }}>
              <div aria-hidden="true" className="art:pointer-events-none art:absolute art:left-0 art:right-0 art:top-16 art:h-80">
                {TICKS.map((tick) => (<div key={tick} className="art:absolute art:left-0 art:right-0 art:flex art:items-center" style={{ bottom: `${tick}%` }}>
                    <span className="art:absolute art:left-0 art:w-8 art:-translate-y-1/2 art:text-right art:text-xs art:tabular-nums art:text-muted-foreground">
                      {String(tick)}
                    </span>
                    <span className={tick === 0 ? "art:ml-10 art:w-full art:border-t art:border-border" : "art:ml-10 art:w-full art:border-t art:border-dashed art:border-border/50"}/>
                  </div>))}
              </div>
              <div className="art:relative art:grid art:gap-10 art:px-5 art:@min-[640px]/artemis:gap-14" style={{ gridTemplateColumns: "repeat(3, minmax(0, 1fr))" }}>
                {METRICS.map((metric, index) => {
            const other = metric.rivals[rival];
            return (<figure key={metric.title} className="art:min-w-0">
                      <div className="art:relative art:h-80">
                        <div aria-hidden="true" className="art:pointer-events-none art:absolute art:left-1/2 art:right-0 art:border-r art:border-t art:border-dashed art:border-foreground/25" style={{ bottom: `${other}%`, height: `${metric.workspace - other}%` }}>
                          <span className="art:absolute art:bottom-full art:right-0 art:mb-2 art:bg-background/90 art:px-1.5 art:py-1 art:text-center art:text-xs art:text-muted-foreground">
                            <span className="art:block art:text-xl art:font-medium art:tabular-nums art:text-foreground">
                              {(metric.workspace / other).toFixed(1)}
                              {"\u00D7"}
                            </span>
                            {"the score"}
                          </span>
                        </div>
                        <Bar value={metric.workspace} side="art:left-0" label="Workspace" gradient="art:from-accent/60 art:to-accent/20" delay={index * 0.06}/>
                        <Bar key={rival} value={other} side="art:right-0" label={rival} gradient="art:from-foreground/15 art:to-foreground/5" delay={index * 0.06 + 0.05}/>
                      </div>
                      <figcaption className="art:pt-6 art:text-center">
                        <h3 className="art:text-xl art:font-medium">
                          {metric.title}
                        </h3>
                        <p className="art:mt-2 art:text-sm art:leading-6 art:text-muted-foreground">
                          {metric.caption}
                        </p>
                      </figcaption>
                    </figure>);
        })}
              </div>
            </div>
          </section>
          <div className="art:mt-7 art:flex art:flex-wrap art:items-start art:justify-between art:gap-3 art:text-xs art:leading-5 art:text-muted-foreground">
            <p className="art:max-w-2xl">
              {"Illustrative scores for fictional products, not measured benchmarks. Replace with verified results and your evaluation methodology."}
            </p>
            <span className="art:inline-flex art:items-center art:gap-2 art:@min-[1024px]/artemis:hidden">
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-left-right art:size-3.5" aria-hidden="true">
                <path d="M8 3 4 7l4 4"/>
                <path d="M4 7h16"/>
                <path d="m16 21 4-4-4-4"/>
                <path d="M20 17H4"/>
              </svg>
              {"Scroll to compare"}
            </span>
          </div>
        </div>
      </section>
    </>);
}

"use client";
// @zeus-internal
import { Listbox, ListboxButton, ListboxOption, ListboxOptions } from "../../../../lib/headless";
export type Competitor = "Option A" | "Option B";
export const COMPETITORS: readonly Competitor[] = ["Option A", "Option B"];
const BUTTON = "art:inline-flex art:items-center art:border art:text-left art:text-foreground art:transition-colors art:hover:border-border-strong art:disabled:pointer-events-none art:disabled:opacity-50 art:outline-none art:ring-0 art:focus:outline-none art:focus:ring-0 art:focus-visible:outline-none art:data-focus:outline-none art:data-focus:ring-0 art:data-open:ring-0 art:h-10 art:min-w-28 art:justify-between art:gap-4 art:rounded-full art:border-transparent art:bg-muted/60 art:px-4 art:text-sm art:font-medium art:hover:bg-muted art:focus-visible:ring-2 art:focus-visible:ring-ring";
const PANEL = "art:z-[120] art:overflow-hidden art:rounded-2xl art:border art:border-border-strong/50 art:bg-background art:p-1.5 art:backdrop-blur-xl art:outline-none art:ring-0 art:focus:outline-none art:focus:ring-0 art:focus-visible:outline-none art:focus-visible:ring-0 art:data-focus:outline-none art:data-focus:ring-0 art:transition art:duration-150 art:ease-out art:data-closed:scale-95 art:data-closed:opacity-0 art:origin-top art:w-[var(--button-width)] art:shadow-none art:max-w-[calc(100vw-1.5rem)]";
const OPTION = "art:group art:flex art:min-h-11 art:cursor-pointer art:items-center art:gap-3 art:rounded-xl art:px-3 art:py-2 art:text-left art:transition-colors art:data-focus:bg-primary/5 art:data-disabled:pointer-events-none art:data-disabled:opacity-50";
export function CompareSelect({ value, onChange, }: {
    value: Competitor;
    onChange: (value: Competitor) => void;
}) {
    return (<Listbox as="div" className="art:relative art:inline-block art:text-left" value={value} onChange={onChange}>
      <ListboxButton aria-label="Compare with" className={BUTTON}>
        {({ open }) => (<>
            <span className="art:min-w-0 art:truncate">{value}</span>
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-chevron-down art:size-4 art:shrink-0 art:text-muted-foreground art:transition-transform${open ? " art:rotate-180" : ""}`} aria-hidden="true">
              <path d="m6 9 6 6 6-6"/>
            </svg>
          </>)}
      </ListboxButton>
      <ListboxOptions anchor={{ to: "bottom start", gap: 8, padding: 12 }} transition className={PANEL}>
        {COMPETITORS.map((name) => (<ListboxOption key={name} value={name} className={OPTION}>
            <span className="art:min-w-0 art:flex-1">
              <span className="art:block art:truncate art:text-sm">{name}</span>
            </span>
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:size-4 art:shrink-0 art:opacity-0 art:group-data-selected:opacity-100" aria-hidden="true">
              <path d="M20 6 9 17l-5-5"/>
            </svg>
          </ListboxOption>))}
      </ListboxOptions>
    </Listbox>);
}
